// Generated by app-probing. Deleted after the run. Never commit.
// Put it next to the project's Playwright config, so the import below resolves.
import { defineConfig } from '@playwright/test';

import base from './playwright.config';

// Paths resolve from this file's folder, like the project's config.
const probe = {
  testDir: './<testDir>/.probe',
  testMatch: '**/*.spec.ts',
  // Playwright applies testIgnore even to a file named on the command line.
  testIgnore: [] as string[],
};

// The project the e2e tests run in, if the config has projects. Run with --project=<this name>.
const E2E_PROJECT = '<project name>';

export default defineConfig({
  ...base,
  // Keeps probes out of the project's reports and test-management uploads.
  reporter: [['list']],
  // With projects, only the e2e project gets the overrides: the projects it depends on, such as an auth
  // setup project, inherit the top-level testDir and must still find their own files.
  ...(base.projects?.length
    ? {
        projects: base.projects.map((project) =>
          project.name === E2E_PROJECT ? { ...project, ...probe } : project,
        ),
      }
    : probe),
});
